function pairScore(rows:any[]){const pairs=new Map<string,any>();for(const r of rows){const key=JSON.stringify([r.MODEL,r.PRODUCT]);const pair=pairs.get(key)||{MODEL:r.MODEL,PRODUCT:r.PRODUCT};for(const field of ['CNT','AVG','MIN','MAX'])pair[field+'_'+r.SOURCE]=r[field];pairs.set(key,pair)}return [...pairs.values()]}
