function ProcessingTimeline({run}:any){const timing=run?.timings;const stages=[['read_parse_normalize','Чтение и нормализация','Читаем ответы и приводим поля к общей структуре'],['union','Объединение данных','Собираем оба среза без потери строк'],['comparison','Сравнение версий','Находим новые, удалённые и изменённые поля'],['segments','Продукты и решения','Связываем результаты с продуктами и моделями'],['aggregations','Сводные показатели','Считаем уникальные заявки в каждой группе'],['parquet','Сохранение результатов','Записываем аналитические таблицы'],['checks','Автоматические проверки','Выполняем подключённые проверки']];return <div className="processing-view"><div className="processing-total"><div><span className="eyebrow">ФАКТИЧЕСКОЕ ВРЕМЯ ОБРАБОТКИ</span><h3>{timing?duration(timing.total):run?.status==='running'?'Обработка идёт…':'Замер пока недоступен'}</h3><p>Длительность работы, а не время начала этапа</p></div><Activity size={32}/></div>{timing?<div className="timing-stages">{stages.map(([key,title,description],i)=><details className="timing-stage" key={key}><summary><span className="stage-index">{String(i+1).padStart(2,'0')}</span><span><b>{title}</b><small>{key==='checks'&&!run.snapshot?.checks?.length?'Проверки не выбраны для этого запуска':description}</small></span><span className="stage-time">{key==='checks'&&!run.snapshot?.checks?.length?'Пропущено':duration(timing[key])}</span><ChevronDown size={16}/></summary><div className="stage-expanded"><div className="stage-meter"><i style={{width:Math.max(1,100*timing[key]/timing.total)+'%'}}/></div><p>{(100*timing[key]/Math.max(timing.total,.000001)).toFixed(1)}% общего времени · замер на сервере</p></div></details>)}</div>:<p className="muted">Точные длительности появятся после завершения. Текущее состояние: {run?.stage||'запуск не выбран'}.</p>}<details className="event-journal"><summary>История выполнения и технические подробности</summary>{(run?.log||[]).map((entry:any,i:number)=>{const end=run.log[i+1]?.time??(run.status==='completed'?run.updated:null);const elapsed=entry.duration_seconds??(end===null?null:Math.max(0,end-entry.time));return <div className="journal-entry" key={i}><b>{entry.stage}</b><span>{duration(elapsed)}</span><small>Начало: {new Date(entry.time*1000).toLocaleTimeString('ru-RU')}</small><pre>{JSON.stringify(entry.detail??entry.traceback??{},null,2)}</pre>{entry.detail?.code&&<details><summary>Исполненный код этапа</summary><CodeEditor value={entry.detail.code} editable={false}/></details>}</div>})}</details></div>}
const fieldName=(r:any)=>({decision:'Решение',value:'Значение',version:'Версия',product_id:'Номер продукта',product_name:'Название продукта',rank:'Позиция в выдаче',type:'Тип предложения',modelName:'Название модели',rejectReason:'Причина отказа',name:'Название',rate:'Ставка',limit:'Лимит',riskSegment:'Сегмент риска',hit:'Срабатывание правила'} as any)[r.KEY]||r.KEY||'Поле';
const fieldValue=(r:any,source:string)=>!r['PRESENT_'+source]?'Поле отсутствует':r['TYPE_'+source]==='null'?'Не задано (null)':human(r['VALUE_'+source]);
function CompareFields({rows,openSource}:any){const groups=new Map<string,any[]>();for(const row of rows){const path=row.PATH||'';const category=path==='decisionResult.decision'?'Итоговое решение':path.includes('available_offers')?'Предложения клиенту':path.includes('product_trials')?'Решения по продуктам':path.includes('scoring')?'Модели и оценки':path.startsWith('ext_data')||path.startsWith('characteristics')?'Внешние данные':'Остальные поля';groups.set(category,[...(groups.get(category)||[]),row])}return <div className="comparison-groups"><div className="compare-guide"><div><span className="eyebrow">КАРТА ИЗМЕНЕНИЙ</span><h3>Что произошло в этой заявке</h3><p>Раскройте раздел, затем нужное поле. Слева — исходная версия, справа — новая.</p></div><span className="compare-count">{rows.length}<small>полей в выборке</small></span></div>{rows.length?[...groups].map(([category,items],groupIndex)=><details className="comparison-group" key={category} open={groupIndex===0}><summary><span className="group-symbol"><Layers3 size={19}/></span><span><b>{category}</b><small>Изменений: {items.filter(r=>r.DIFF_FLAG).length} · Полей: {items.length}</small></span><span className="group-peek">{items[0]&&fieldValue(items[0],'BEFORE')} → {items[0]&&fieldValue(items[0],'AFTER')}</span><ChevronDown size={19}/></summary><div className="field-list">{items.map((r:any,i:number)=><details className={'field-card '+r.CHANGE_TYPE} key={r.PATH+r.KEY_JSON} open={groupIndex===0&&i===0}><summary className="field-summary"><span><strong>{fieldName(r)}</strong><small>{human(r.CHANGE_TYPE)}</small></span><span className="compact-values"><span>{fieldValue(r,'BEFORE')}</span><ArrowUpRight size={15}/><b>{fieldValue(r,'AFTER')}</b></span><ChevronDown size={16}/></summary><div className="field-expanded"><div className="value-pair"><div><span>Было</span><b>{fieldValue(r,'BEFORE')}</b></div><ArrowUpRight size={20}/><div><span>Стало</span><b>{fieldValue(r,'AFTER')}</b></div></div><div className="field-context"><span>Где находится поле</span><code>{r.PATH}</code>{r.ARRAY_KEY&&<small>Элемент: {r.ARRAY_KEY}</small>}</div><button className="text source-link" onClick={()=>openSource(r)}>Показать в исходных данных <ArrowUpRight size={14}/></button></div></details>)}</div></details>):<div className="empty">В этой заявке нет полей для выбранного режима.</div>}</div>}
function readPivotLayout(){
 try{
  const layout=JSON.parse(new URLSearchParams(location.search).get('layout')||'null');
  const allowed=new Set([...defaultDims,'DIFF_FLAG','SOURCE','PATH','CHANGE_TYPE']);
  const valid=(v:any)=>Array.isArray(v)&&v.length>0&&v.every(d=>typeof d==='string'&&allowed.has(d));
  if(layout&&valid(layout.dims)&&valid(layout.columns)&&Number.isInteger(layout.level)&&layout.level>=1&&layout.level<=layout.dims.length&&layout.filters&&typeof layout.filters==='object'&&!Array.isArray(layout.filters))return layout;
 }catch{}
 return {dims:defaultDims,columns:['DIFF_FLAG','SOURCE'],level:2,filters:{}};
}
const initialPivot=readPivotLayout();
function AdminPanel({projects}:any){const[users,setUsers]=useState<any[]>([]),[error,setError]=useState('');const load=()=>api('/admin/users').then(setUsers).catch(e=>setError(e.message));useEffect(()=>{load()},[]);const update=async(id:string,body:any)=>{try{await api('/admin/users/'+id,body);await load()}catch(e:any){setError(e.message)}};return <section className="panel"><div className="panel-head"><h2>Пользователи и роли</h2></div>{error&&<p role="alert">{error}</p>}<div className="form-pad">{users.map(u=><details key={u.id}><summary>{u.name} · {u.admin?'Администратор':u.memberships.length?'Участник':'Ожидает доступа'}</summary><button onClick={()=>update(u.id,{admin:!u.admin})}>{u.admin?'Снять права администратора':'Назначить администратором'}</button>{projects.map((p:any)=><label key={p.id}>{p.name}<select value={u.memberships.find((m:any)=>m.project===p.id)?.role||'none'} onChange={e=>update(u.id,{project:p.id,role:e.target.value})}><option value="none">Нет доступа</option><option value="observer">Наблюдатель</option><option value="analyst">Аналитик</option><option value="lead">Ведущий аналитик</option></select></label>)}</details>)}</div></section>}
function OptionalModules({project,onDataset}:any){const[mode,setMode]=useState('demo');const[rows,setRows]=useState(''),[filters,setFilters]=useState('{}'),[pool,setPool]=useState(''),[before,setBefore]=useState('.5'),[after,setAfter]=useState('.4'),[direction,setDirection]=useState('le'),[message,setMessage]=useState('');const[pools,setPools]=useState<any[]>([]);const load=()=>api('/projects/'+project+'/records?kind=pool').then(setPools);useEffect(()=>{if(project)load()},[project]);const act=async(fn:any)=>{try{await fn()}catch(e:any){setMessage(e.message)}};return <section className="panel"><div className="panel-head"><h2>Модули 1–2 · опционально</h2><span className="tag">Демонстрационная СПР</span></div><div className="form-pad"><p>Готовые ответы авторов загружайте через «Данные». Этот режим создаёт собственный пул и два среза по явным правилам.</p><h3>1. Подготовка пула</h3><label>Заявки JSON<input type="file" accept=".json" onChange={e=>{const f=e.target.files?.[0];if(f)f.text().then(setRows)}}/></label><textarea aria-label="Заявки пула" rows={6} value={rows} onChange={e=>setRows(e.target.value)} placeholder={'[{"id":"1","score":0.3,"stops":[false],"product":"demo"}]'}/><label>Фильтры JSON<input value={filters} onChange={e=>setFilters(e.target.value)}/></label><button onClick={()=>act(async()=>{const r=await api('/projects/'+project+'/pools',{rows:JSON.parse(rows),filters:JSON.parse(filters)});setPool(r.id);setMessage('В пуле: '+r.count);await load()})}>Подготовить пул</button><h3>2. Прогон двух версий</h3><label>Исполнитель<select value={mode} onChange={e=>setMode(e.target.value)}><option value="demo">Демонстрационные правила</option><option value="http">Подключённая СПР · HTTP</option></select></label><select aria-label="Пул заявок" value={pool} onChange={e=>setPool(e.target.value)}><option value="">Выберите пул</option>{pools.map(p=><option key={p.id} value={p.id}>{p.name} · {p.body.rows.length}</option>)}</select><label>Порог BEFORE<input type="number" value={before} onChange={e=>setBefore(e.target.value)}/></label><label>Порог AFTER<input type="number" value={after} onChange={e=>setAfter(e.target.value)}/></label><select value={direction} onChange={e=>setDirection(e.target.value)}><option value="le">Меньше или равно — одобрение</option><option value="ge">Больше или равно — одобрение</option></select><button disabled={!pool} onClick={()=>act(async()=>{const r=await api('/projects/'+project+'/pools/'+pool+'/execute',{mode,versions:{BEFORE:{cutoff:+before,direction},AFTER:{cutoff:+after,direction}}});onDataset(r.id);setMessage('Созданы два среза. Выберите профиль main и запустите сравнение в конструкторе.')})}>Создать два среза</button><p role="status">{message}</p></div></section>}
const cyrillic = /\p{Script=Cyrillic}/u;
function AuthForm({registerMode,setRegisterMode,busy,error,notice,clear,submit,onDemo}:any){
 const [demo,setDemo]=useState(false);
 useEffect(()=>{api('/health').then(r=>setDemo(r.demo_login)).catch(()=>{});},[]);
 const[password,setPassword]=useState(''),[visible,setVisible]=useState(false);
 const invalid=registerMode&&cyrillic.test(password);
 useEffect(()=>{setPassword('');setVisible(false)},[registerMode]);
 return <div className="login"><div className="login-brand"><div className="logo"><Layers3/></div><span>скорифай</span></div><form onSubmit={e=>{e.preventDefault();if(!invalid)submit(Object.fromEntries(new FormData(e.currentTarget)))}} aria-busy={busy}>
 <p className="eyebrow">АНАЛИТИКА РЕШЕНИЙ СПР</p><h1>{registerMode?'Создать аккаунт':'Войти в Скорифай'}</h1><p className="muted">{registerMode?'После регистрации администратор предоставит доступ к проекту.':'Войдите в свой аккаунт, чтобы работать с данными проекта.'}</p>
 <label>Имя пользователя<input name="name" required minLength={registerMode?3:undefined} maxLength={registerMode?80:undefined} autoComplete="username" autoCapitalize="none" spellCheck={false}/></label>
 <label htmlFor="auth-password">Пароль</label><div className="password-field"><input id="auth-password" name="password" type={visible?'text':'password'} required minLength={registerMode?12:undefined} autoComplete={registerMode?'new-password':'current-password'} value={password} onChange={e=>setPassword(e.target.value)} aria-invalid={invalid} aria-describedby="password-help"/><button type="button" aria-label={visible?'Скрыть пароль':'Показать пароль'} aria-pressed={visible} onClick={()=>setVisible(!visible)}>{visible?'Скрыть':'Показать'}</button></div>
 <small id="password-help" className={invalid?'error':''} aria-live="polite">{invalid?'В пароле есть кириллица. Переключите раскладку на английскую и замените русские буквы.':registerMode?'Не менее 12 символов. Без кириллицы; можно использовать латинские буквы, цифры и символы.':demo?'Для пользователя admin введите пароль администратора сервера.':'Введите пароль вашего аккаунта.'}</small>
 {error&&<p role="alert" className="error">{error}</p>}{notice&&<p role="status" className="success">{notice}</p>}
 <button className="primary" disabled={busy||invalid}>{busy?'Подождите…':registerMode?'Создать аккаунт':'Войти'} <ArrowUpRight size={18}/></button><button disabled={busy} type="button" className="text" onClick={()=>{setRegisterMode(!registerMode);clear()}}>{registerMode?'Уже есть аккаунт — войти':'Создать аккаунт'}</button>
 {!registerMode&&demo&&<div className="auth-demo-option"><p>Посмотрите готовое сравнение на открытых данных.</p>
   <button type="button" disabled={busy} onClick={onDemo}>Открыть готовый демоотчёт <ArrowUpRight size={16}/></button>
 </div>}</form></div>
}
function ResultTable({rows,cols,click}:any){const[page,setPage]=useState(0);useEffect(()=>setPage(0),[JSON.stringify(rows)]);const offset=Math.min(page,Math.max(0,Math.ceil(rows.length/10)-1))*10;return <><div className="table-wrap"><table><thead><tr>{cols.map((c:string)=><th key={c}>{labels[c]||c}</th>)}</tr></thead><tbody>{rows.slice(offset,offset+10).map((r:any,i:number)=><tr key={i}>{cols.map((c:string,j:number)=><td key={c}>{click&&j===0?<button className="text" onClick={()=>click(r)}>{cellText(c,r[c])} <ChevronRight size={14}/></button>:typeof r[c]==='object'?JSON.stringify(r[c]):cellText(c,r[c])}</td>)}</tr>)}</tbody></table>{!rows.length&&<div className="empty">Нет строк. Измените фильтры или выберите другой прогон.</div>}</div>{rows.length>10&&<div className="pagination"><button disabled={!offset} onClick={()=>setPage(page-1)}>Назад</button><span aria-live="polite">{offset+1}–{Math.min(offset+10,rows.length)} из {rows.length}</span><button disabled={offset+10>=rows.length} onClick={()=>setPage(page+1)}>Далее</button></div>}</>}
function SourceDocuments({native,quality}:any){
 const both=typeof native.BEFORE==='string'&&typeof native.AFTER==='string';
 const diff=React.useMemo(()=>both?sourceDiff(native.BEFORE,native.AFTER):null,[native.BEFORE,native.AFTER,both]);
 return <><div className="source-legend" aria-label="Обозначения изменений"><span className="source-changed">~ Изменено</span><span className="source-added">+ Добавлено</span><span className="source-removed">− Удалено</span></div><p className="muted">{!both?'Для подсветки нужны оба исходных документа.':diff&&[...diff.before,...diff.after].every(line=>line.kind==='same')?'Исходные документы совпадают.':'Подсвечены различия в тексте документов, включая служебные поля. Номера слева — строки исходного документа.'}</p><div className="native-grid">{['BEFORE','AFTER'].map(src=>{const lines=diff?(src==='BEFORE'?diff.before:diff.after):null;return <section key={src}><h3>{src==='BEFORE'?'До изменений':'После изменений'}</h3>{lines?<pre className="source-diff" tabIndex={0} aria-label={src==='BEFORE'?'Исходный документ до изменений':'Исходный документ после изменений'}><code>{lines.map((line,i)=><span key={i} className={'source-line source-'+line.kind}><span className="source-line-number" aria-hidden="true">{i+1}</span><span className="source-line-marker" aria-label={{same:'Без изменений',added:'Добавлено',removed:'Удалено',changed:'Изменено'}[line.kind]}>{ {same:' ',added:'+',removed:'−',changed:'~'}[line.kind]}</span><span>{line.text||' '}{i<lines.length-1?'\n':''}</span></span>)}</code></pre>:<pre>{native[src]??native['ERROR_'+src]??quality?.find((q:any)=>q.SOURCE===src)?.ERROR??'Нет документа'}</pre>}</section>})}</div></>
}
function DatasetSelect({datasets, value, onChange, busy}: {
  datasets: {id:string;name:string}[];
  value: string;
  onChange: (value:string) => void;
  busy: boolean;
}) {
  return <label>Датасет<select aria-label="Датасет" value={value} disabled={!datasets.length}
    onChange={event=>onChange(event.target.value)}>
    {!datasets.length && <option value="">{busy ? 'Загружаем датасеты…' : 'Нет датасетов'}</option>}
    {datasets.map(dataset=><option key={dataset.id} value={dataset.id}>{dataset.name}</option>)}
  </select></label>;
}

function useReport(path: string, body?: any) {
  const key = JSON.stringify([path,body]);
  const [report,setReport] = useState<{key:string;data?:any;error?:string}>({key:''});
  useEffect(() => {
    if (!path) return;
    let alive=true;
    api(path,body).then(data=>{if(alive)setReport({key,data})})
      .catch(e=>{if(alive)setReport({key,error:e.message})});
    return ()=>{alive=false};
  },[key]);
  return report.key===key ? report : {data:undefined,error:undefined};
}

const route = new URLSearchParams(location.search);
const initialTab = route.get('tab');
function initialMode(): InterfaceMode {
  const fromLink = route.get('mode');
  if (fromLink==='simple'||fromLink==='advanced') return fromLink;
  if (initialTab && !isSimpleTab(initialTab)) return 'advanced';
  try {return localStorage.getItem('scorify.interfaceMode')==='advanced'?'advanced':'simple';}
  catch {return 'simple';}
}

