const uploadFiles=(source:string,files:File[])=>handle(async()=>{
  let count=0;
  const uploadKey=JSON.stringify([project,dataset,source]);
  setUploadStatus({key:uploadKey,state:'loading',total:files.length,stored:0});
  try {
    for(let i=0;i<files.length;i+=100){
      const form=new FormData();
      form.set('dataset',dataset);
      form.set('source',source);
      files.slice(i,i+100).forEach(file=>form.append('files',file));
      const response=await fetch(`/api/projects/${project}/upload`,{method:'POST',body:form});
      const body=await response.json();
      if(!response.ok)throw Error(body.detail);
      count+=body.stored;
      setUploadStatus({key:uploadKey,state:'loading',total:files.length,stored:count});
    }
    setUploadStatus({key:uploadKey,state:'done',total:files.length,stored:count});
    setNotice(simple?`Загружено файлов: ${count}.`:`Сохранено ${count} ответов. Запустите обработку для валидации.`);
  } catch(e:any) {
    setUploadStatus({key:uploadKey,state:'error',total:files.length,stored:count,error:e.message});
    throw e;
  } finally {
    setFileRevision(value=>value+1);
  }
});
