const download=async(format:string)=>{
  const query=new URLSearchParams({format,analysis:JSON.stringify(payload)});
  if(format==='json'||format==='csv')query.set('flat','true');
  if(!simple&&tab==='pivot'){
    query.set('filters',JSON.stringify(filters));
    query.set('dimensions',JSON.stringify([...dims.slice(0,level),...columns]));
  }
  setError('');
  setDownloading(format);
  try{
    const response=await fetch(`/api/runs/${runid}/export?${query}`);
    if(!response.ok){
      const detail=(await response.json().catch(()=>null))?.detail;
      throw Error(typeof detail==='string'?detail:'Не удалось подготовить отчёт. Попробуйте ещё раз.');
    }
    const file=URL.createObjectURL(await response.blob());
    const link=document.createElement('a');
    link.href=file;
    link.download=`scorify-${runid}.${format}`;
    document.body.append(link);
    link.click();
    link.remove();
    setTimeout(()=>URL.revokeObjectURL(file),1000);
  }catch(e:any){setError(e.message)}finally{setDownloading('')}
};

