{tab==='overview'&&<><section className="welcome"><div><span className="eyebrow">ОТ ОБЩЕЙ КАРТИНЫ К ДЕТАЛЯМ</span><h2>Поймите каждое изменение.</h2><p>Сравните версии, найдите затронутые заявки и проверьте исходные данные.</p></div><div className="journey"><span><b>01</b> Выберите число</span><ChevronRight size={16}/><span><b>02</b> Откройте заявку</span><ChevronRight size={16}/><span><b>03</b> Сравните поля</span></div></section><div className="kpis">{[['Обнаружено заявок',s.discovered,'Включая неполные пары',()=>openDrill('Все обнаруженные заявки','quality')],['Валидных пар',s.valid_pairs,`${fmt(s.discovered?100*s.valid_pairs/s.discovered:0)}% обнаруженных`,()=>openDrill('Валидные пары','segments',{}, {paired:true})],['С изменениями',s.changed_apps,`${fmt(s.valid_pairs?100*s.changed_apps/s.valid_pairs:0)}% валидных пар`,()=>openDrill('Заявки с изменениями','facts',{diff_flag:1})],['Сменилось решение',s.decision_changed,'База: валидные пары',()=>openDrill('Смена решения','segments',{DECISION_CHANGED:1})]].map(([label,n,caption,fn]:any,i)=><button className={'kpi kpi-'+i} key={label} onClick={fn}><div>{label}<ArrowUpRight size={17}/></div><strong>{fmt(n)}</strong><small>{caption}</small><span className="kpi-link">Посмотреть заявки <ArrowUpRight size={13}/></span></button>)}</div><details className="advanced-options"><summary>Подробности по продуктам и партнёрам</summary><section className="panel"><h2>Изменения без смены решения</h2><button onClick={()=>openDrill('Изменения без смены решения','facts',{diff_flag:1,DECISION_CHANGED:0})}>{fmt(overview.data?.changed_without_decision)} заявок</button></section><div className="grid2">{Object.entries(overview.data?.impact||{}).map(([dim,rows])=><section className="panel" key={dim}><h2>{({PRODUCT:'Затронутые продукты',PARTNER:'Затронутые партнёры',ROUTING_METHOD:'Маршруты обработки'} as any)[dim]}</h2>{table(rows as any[],[dim,'CNT'],r=>openDrill('Изменения: '+String(r[dim]),'facts',{DIFF_FLAG:1,[dim]:r[dim]}))}</section>)}</div><ProductChanges items={factorChanges.data?.items} ready={ready} open={openDrill}/></details><div className="insight"><div className="insight-icon"><Activity size={21}/></div><div><b>{fmt(s.changed_apps)} заявок требуют анализа изменений</b><p>У {fmt(overview.data?.changed_without_decision)} из них итоговое решение сохранилось. Внешние данные изменились у {fmt(overview.data?.external)}. Совпадение изменений не доказывает причинность.</p></div><button onClick={()=>setTab('checks')}>К проверкам <ArrowUpRight size={16}/></button></div><div className="grid2"><section className="panel"><div className="panel-head"><div><h2>Переходы решений</h2><p>Число уникальных заявок в выборке</p></div><span className="tag">До → после</span></div><div className="transitions">{overview.data?.transitions.map((r:any,i:number)=><button key={i} onClick={()=>openDrill('Переход решения','segments',{DECISION_BEFORE:r.DECISION_BEFORE,DECISION_AFTER:r.DECISION_AFTER})}><span className="decision">{human(r.DECISION_BEFORE)}</span><span className="flow"><i style={{width:Math.max(4,r.CNT/s.discovered*100)+'%'}}/></span><span className={'decision '+(r.DECISION_BEFORE!==r.DECISION_AFTER?'changed':'')}>{human(r.DECISION_AFTER)}</span><b>{fmt(r.CNT)}</b><ArrowUpRight size={14}/></button>)}</div><div className="panel-footer">Нажмите на переход, чтобы открыть заявки</div></section><FieldChanges groups={overview.data?.top_groups} ready={ready} open={openDrill} allFields={()=>setTab('pivot')}/></div><div className="grid2"><section className="panel"><div className="panel-head"><h2>Качество входных данных</h2><button className="text" onClick={()=>setTab('quality')}>Подробнее <ArrowUpRight size={15}/></button></div><div className="quality-summary"><div className="ring" style={{background:`conic-gradient(#1c8978 ${(s.discovered ? s.valid_pairs/s.discovered*100 : 0)}%,#f0d8b8 0)`}}><div><b>{fmt(s.discovered?100*s.valid_pairs/s.discovered:0)}%</b><small>пригодных пар</small></div></div><div><p><i className="dot"/>Валидных пар <b>{fmt(s.valid_pairs)}</b></p><p><i className="dot amber"/>Исключено <b>{fmt(s.excluded)}</b></p><small>Исключения не входят в показатели сравнения.</small></div></div></section><section className="panel"><div className="panel-head"><h2>Результаты проверок</h2></div><div className="form-pad"><button onClick={()=>setTab('checks')}>Открыть распределения и переходы</button></div></section></div><section className="panel"><div className="panel-head"><h2>Наблюдения и следующий шаг</h2><span className="tag">На основании данных</span></div>{overview.data?.recommendations.map((r:any,i:number)=><div className="recommendation" key={i}><span className="rank">0{i+1}</span><div><b>{r.observation}</b><p>{r.hypothesis||r.next}</p><small>{r.confidence} · {r.next}</small></div>{r.filters&&<button onClick={()=>openDrill(r.observation,'facts',r.filters)}>Открыть данные</button>}</div>)}</section></>}
{tab==='pivot'&&<section className="panel"><div className="panel-head"><div><h2>Изменяемая сводная</h2><p>В каждой ячейке показано число разных заявок. Одна заявка может входить в несколько групп.</p></div><button aria-label="Полный экран" onClick={()=>document.documentElement.requestFullscreen?.()}><Maximize2 size={17}/></button></div><div className="pivot-tools"><label>Строки<select value={dims.join(',')} onChange={e=>{setDims(e.target.value.split(','));setLevel(2);setPivotOffset(0)}}><option value={defaultDims.join(',')}>Путь → класс → суффикс → элемент → поле → значение</option><option value="PRODUCT,PARTNER,PATH,VALUE_ADJUSTED">Продукт → партнёр → атрибут → значение</option><option value="ROUTING_METHOD,PATH,VALUE_ADJUSTED">Сегмент маршрутизации → атрибут → значение</option><option value="KEY,VALUE_ADJUSTED,CLASS,ARRAY_KEY">Поле → значение → класс → элемент</option><option value="CHANGE_TYPE,PATH,ARRAY_KEY,VALUE_ADJUSTED">Тип изменения → путь → элемент → значение</option><option value="PATH,ARRAY_KEY,VALUE_ADJUSTED">Канонический путь → элемент → значение</option></select></label><label>Колонки<select aria-label="Колонки" value={columns.join(',')} onChange={e=>setColumns(e.target.value.split(','))}><option value="DIFF_FLAG,SOURCE">Изменение × срез</option><option value="SOURCE,DIFF_FLAG">Срез × изменение</option><option value="SOURCE">Только срез</option><option value="CHANGE_TYPE,SOURCE">Тип изменения × срез</option></select></label><label>Уровней<select value={level} onChange={e=>{setLevel(+e.target.value);setPivotOffset(0)}}>{dims.map((_,i)=><option key={i} value={i+1}>{i+1}</option>)}</select></label><label>Фильтр<select aria-label="Фильтр" value={filters.DIFF_FLAG??''} onChange={e=>{let f={...filters};if(e.target.value==='')delete f.DIFF_FLAG;else f.DIFF_FLAG=+e.target.value;setFilters(f);setPivotOffset(0)}}><option value="">Все атрибуты</option><option value="1">Только изменения</option><option value="0">Без изменений</option></select></label></div><div className="toolbar"><button onClick={()=>handle(async()=>{await record('view','Раскладка '+new Date().toLocaleTimeString(),{runid,dims,level,columns,filters});await refresh();setNotice('Раскладка сохранена')})}>Сохранить раскладку</button><select aria-label="Сохранённые раскладки" value="" onChange={e=>{let b=records.find(r=>r.id===e.target.value)?.body;if(b){setDims(b.dims);setLevel(b.level);setColumns(b.columns);setFilters(b.filters)}}}><option value="">Открыть сохранённую…</option>{records.filter(r=>r.kind==='view').map(r=><option key={r.id} value={r.id}>{r.name}</option>)}</select><button onClick={()=>{setDims(defaultDims);setLevel(2);setColumns(['DIFF_FLAG','SOURCE']);setFilters({});setPivotOffset(0)}}>Сбросить</button><button disabled={!!downloading} onClick={()=>download('csv')}><Download size={15}/>Все факты CSV</button><button disabled={!!downloading} onClick={()=>download('json')}>JSON</button></div>{Object.keys(filters).length>0&&<div className="filter-pills">{Object.entries(filters).map(([k,v])=><button key={k} onClick={()=>{let f={...filters};delete f[k];setFilters(f)}}>{k}: {String(v)} <X size={13}/></button>)}</div>}<PivotTable rows={pivot} dims={dims.slice(0,level)} columns={columns} open={(f)=>openDrill('Заявки выбранной ячейки','facts',{...filters,...f})} expand={f=>{setFilters({...filters,...f});setLevel(Math.min(dims.length,level+1))}}/><div className="pagination"><button disabled={!pivotOffset} onClick={()=>setPivotOffset(Math.max(0,pivotOffset-250))}>Назад</button><span>Строки фактов {pivotOffset+1}–{pivotOffset+pivot.length}</span><button disabled={pivot.length<250} onClick={()=>setPivotOffset(pivotOffset+250)}>Далее</button></div><div className="panel-footer">Стрелка раскрывает иерархию. Число открывает точный список заявок. Пустая ячейка означает отсутствие фактов.</div></section>}
