{tab==='scenario'&&canWrite&&<><div className="info"><FlaskConical size={20}/><div><b>Отдельный расчёт порога продукта</b><p>Меняется порог одного продукта. Используются балл и стоп-факторы после изменений. Остальная банковская стратегия не воспроизводится; исходные ответы неизменны.</p></div></div><section className="panel"><div className="form-pad scenario-form"><label>ID продукта<input value={product} onChange={e=>setProduct(e.target.value)}/></label><label>Новый порог<input value={cutoff} type="number" min="0" max="1" step="0.01" onChange={e=>setCutoff(e.target.value)}/></label><label>Условие одобрения<select value={direction} onChange={e=>setDirection(e.target.value)}><option value="ge">Балл ≥ порога</option><option value="le">Балл ≤ порога</option></select></label><button className="primary" disabled={busy} onClick={()=>handle(async()=>{setSimulation(await api(`/runs/${runid}/scenario`,{product,cutoff:+cutoff,direction,analysis:payload}));await refresh()})}><Play size={15}/>Рассчитать сценарий</button></div></section>{simulation&&<section className="panel"><div className="panel-head"><div><h2>Изменилось {simulation.changed} из {simulation.total} решений продукта</h2><p>Исключено из симуляции: {simulation.excluded}. {simulation.limitations}</p></div><span className="tag">СИМУЛЯЦИЯ</span></div>{table(simulation.items,['APP_ID','MODEL','SCORE','CUTOFF','DECISION','SIMULATED'],r=>{openDrill('Сценарий','products',{PRODUCT:product});setAppid(r.APP_ID)})}</section>}<section className="panel"><div className="panel-head"><h2>Сохранённые расчёты порога</h2></div>{table(records.filter(r=>r.kind==='scenario').map(r=>({id:r.id,name:r.name,base:r.body.base,changed:r.body.changed,total:r.body.total})),['name','base','changed','total'],r=>{const saved=records.find(x=>x.id===r.id).body;if(saved.base!==runid){setError('Выберите базовый прогон сценария: '+saved.base);return}setProduct(saved.product);setSimulation(saved)})}</section></>}
